<?php declare(strict_types=1); require_once __DIR__.'/includes/auth.php'; require_auth(); require_once __DIR__.'/config/database.php'; $page_title='Dashboard';$page_heading='Document dashboard';$active_page='dashboard';$userId=(int)$_SESSION['user_id'];
function dashboard_rows(mysqli $db,string $where,int $userId):array{$sql="SELECT d.id_track,d.title,d.status AS document_status,l.status,l.date,l.sender,l.receiver,CONCAT_WS(', ',su.lname, NULLIF(CONCAT(su.fname,' ',su.mname),'')) sender_name,CONCAT_WS(', ',ru.lname, NULLIF(CONCAT(ru.fname,' ',ru.mname),'')) receiver_name FROM dr_documents d JOIN dr_logs l ON l.id=(SELECT id FROM dr_logs WHERE id_track=d.id_track ORDER BY id DESC LIMIT 1) LEFT JOIN dr_users su ON su.id=l.sender LEFT JOIN dr_users ru ON ru.id=l.receiver WHERE $where ORDER BY l.id DESC";$stmt=$db->prepare($sql);$stmt->bind_param('i',$userId);$stmt->execute();return $stmt->get_result()->fetch_all(MYSQLI_ASSOC);}
$incoming=dashboard_rows($conn,"l.receiver=? AND l.status='Pending'",$userId);$receivable=dashboard_rows($conn,"l.receiver=? AND l.status<>'Pending' AND l.status<>'Closed' AND d.status='open'",$userId);$outgoing=dashboard_rows($conn,"l.sender=? AND l.status='Pending'",$userId);$released=dashboard_rows($conn,"d.author=? AND l.status<>'Pending' AND l.status<>'Closed'",$userId);$closed=dashboard_rows($conn,"d.author=? AND d.status='closed'",$userId);
require __DIR__.'/includes/app-shell.php'; ?>
<section class="stats"><article class="stat card"><span>Incoming</span><strong><?= count($incoming) ?></strong></article><article class="stat card"><span>Receivables</span><strong><?= count($receivable) ?></strong></article><article class="stat card"><span>Outgoing</span><strong><?= count($outgoing) ?></strong></article><article class="stat card"><span>Released</span><strong><?= count($released) ?></strong></article><article class="stat card"><span>Closed</span><strong><?= count($closed) ?></strong></article></section>
<?php function document_section(string $title,array $rows,string $empty):void { ?><section><div class="section-heading"><h2><?= e($title) ?></h2></div><div class="panel data-wrap"><?php if(!$rows): ?><div class="empty"><strong><?= e($empty) ?></strong><br>Documents will appear here as their routing status changes.</div><?php else: ?><table class="data-table"><thead><tr><th>Date</th><th>Tracking no.</th><th>Title</th><th>Sender / receiver</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= e($row['date']) ?></td><td><?= e($row['id_track']) ?></td><td><?= e($row['title']) ?></td><td><?= e(($row['sender_name'] ?: 'Unknown').' → '.($row['receiver_name'] ?: 'Unknown')) ?></td><td><span class="badge <?= status_class($row['status']) ?>"><?= e($row['status']) ?></span></td><td><a class="btn btn-secondary" href="<?= url('documents/view.php?tracking='.rawurlencode($row['id_track'])) ?>">View</a></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div></section><?php } document_section('Incoming documents',$incoming,'No incoming documents');document_section('Receivables',$receivable,'No receivable documents');document_section('Outgoing documents',$outgoing,'No outgoing documents');document_section('Released / forwarded documents',$released,'No released documents');document_section('Closed documents',$closed,'No closed documents'); require __DIR__.'/includes/footer.php'; ?>
